//! `cargo xtask regen`: writes example dev directories full of generated files, for testing
//! and benchmarking `cargo xtask pkgen` and the chunker on packs bigger than the hand-made
//! examples
//!
//! generated by claude, needs rewrite sometime (C7)

use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};

use clap::{Args, ValueEnum};
use runtime_consts::pack::{LARGE_FILE_THRESHOLD, ZSTD_LEVEL};
use runtime_consts::paths::TBPK_GENERATOR_OUT;
use runtime_consts::units::{KIB, MIB};
use snafu::{Report, ResultExt, Snafu, ensure};
use tracing::{error, info};

use crate::pkgen;

/// generated examples go here, relative to the workspace root. the folder is gitignored
const EXAMPLES_DIR: &str = "tests/examples/source_to_tbpk/generated";
/// packs from `--auto` go in a folder per example under here, so they don't overwrite each other
const PACKS_DIR: &str = TBPK_GENERATOR_OUT;

/// files per pack folder, so no single folder gets huge
const FILES_PER_GROUP: usize = 20;

/// default `--min` and `--max` for `--type random`
const DEFAULT_RANDOM_MIN: u64 = 1;
const DEFAULT_RANDOM_MAX: u64 = MIB;

/// the size classes, in bytes, inclusive. large starts above the 256 KiB large file threshold
const XSMALL: (u64, u64) = (1, 64);
const SMALL: (u64, u64) = (65, 4 * KIB);
const LARGE: (u64, u64) = (LARGE_FILE_THRESHOLD + 1, 4 * MIB);
const XLARGE: (u64, u64) = (8 * MIB, 16 * MIB);

/// byte values low entropy runs are made of
const LOW_BYTES: [u8; 4] = [0x00, 0x20, 0x41, 0xff];
/// how many words med entropy files are built from
const MED_WORDS: usize = 256;

#[derive(Debug, Args)]
pub struct RegenArgs {
    /// Which example to make. Without it, one of each type is made at its default count
    #[arg(long = "type", value_enum)]
    kind: Option<KindArg>,

    /// Files per side, shared files count for both. Defaults per type
    #[arg(long, requires = "kind", value_parser = clap::value_parser!(u64).range(1..))]
    count: Option<u64>,

    /// Smallest file in bytes, `--type random` only [default: 1]
    #[arg(long, requires = "kind")]
    min: Option<u64>,

    /// Largest file in bytes, `--type random` only [default: 1048576 (1 MiB)]
    #[arg(long, requires = "kind")]
    max: Option<u64>,

    /// How well the files compress
    #[arg(long, value_enum, default_value_t = Entropy::High)]
    entropy: Entropy,

    /// Pack each example afterwards like `cargo xtask pkgen`, packs go to `out/tbpk_generator/<name>`
    #[arg(long)]
    auto: bool,
}

/// `--type` as given, before `--min` and `--max` are folded into `Kind::Random`
#[derive(Clone, Copy, Debug, ValueEnum)]
enum KindArg {
    /// 1 - 64 B, 500 files by default
    Xsmall,
    /// 65 B - 4 KiB, 250 files by default
    Small,
    /// 256 KiB + 1 B - 4 MiB, 25 files by default
    Large,
    /// 8 - 16 MiB, 25 files by default
    Xlarge,
    /// small and large, 100 files by default
    Mix,
    /// every class above, 100 files by default
    Xmix,
    /// --min to --max, 50 files by default
    Random,
}

/// flags that clap can't check on its own
#[derive(Debug, Snafu)]
pub enum ArgsError {
    #[snafu(display("--count is {count}, which doesn't fit in memory on this machine"))]
    CountTooBig { count: u64 },

    #[snafu(display("--min {min} is bigger than --max {max}"))]
    MinOverMax { min: u64, max: u64 },

    #[snafu(display("--min and --max only work with --type random, not --type {kind}"))]
    MinMaxNeedRandom { kind: &'static str },
}

/// `cargo xtask regen` couldn't make or pack every example
#[derive(Debug, Snafu)]
pub enum RegenError {
    #[snafu(display("invalid regen flags"))]
    InvalidArgs { source: ArgsError },

    #[snafu(display("{failed} of {total} examples failed, see the errors above"))]
    SomeFailed { failed: usize, total: usize },
}

/// an example folder couldn't be written
#[derive(Debug, Snafu)]
enum GenerateError {
    #[snafu(display("failed to remove the half written example `{}` left by an earlier run", path.display()))]
    RemoveTmp {
        path: PathBuf,
        source: std::io::Error,
    },

    #[snafu(display("failed to create folder `{}`", path.display()))]
    CreateFolder {
        path: PathBuf,
        source: std::io::Error,
    },

    #[snafu(display("failed to write example file `{pack_path}` to `{}`", full_path.display()))]
    WriteFile {
        pack_path: String,
        full_path: PathBuf,
        source: std::io::Error,
    },

    #[snafu(display("failed to write manifest `{}`", path.display()))]
    WriteManifest {
        path: PathBuf,
        source: std::io::Error,
    },

    #[snafu(display(
        "failed to move the finished example from `{}` to `{}`",
        from.display(),
        to.display()
    ))]
    Rename {
        from: PathBuf,
        to: PathBuf,
        source: std::io::Error,
    },
}

/// how random the file bytes are, which decides how well they compress
#[derive(Clone, Copy, Debug, PartialEq, Eq, ValueEnum)]
enum Entropy {
    /// long runs of a few byte values
    Low,
    /// a small set of random words repeated in random order, with some noise
    Med,
    /// every byte random
    High,
}

#[derive(Clone, Copy, Debug)]
enum Kind {
    XSmall,
    Small,
    Large,
    XLarge,
    /// small and large files
    Mix,
    /// files from every size class
    XMix,
    Random {
        min: u64,
        max: u64,
    },
}

impl Kind {
    fn from_arg(kind: KindArg, min: Option<u64>, max: Option<u64>) -> Result<Self, ArgsError> {
        let kind = match kind {
            KindArg::Xsmall => Kind::XSmall,
            KindArg::Small => Kind::Small,
            KindArg::Large => Kind::Large,
            KindArg::Xlarge => Kind::XLarge,
            KindArg::Mix => Kind::Mix,
            KindArg::Xmix => Kind::XMix,
            KindArg::Random => {
                let min = min.unwrap_or(DEFAULT_RANDOM_MIN);
                let max = max.unwrap_or(DEFAULT_RANDOM_MAX);
                ensure!(min <= max, MinOverMaxSnafu { min, max });
                return Ok(Kind::Random { min, max });
            }
        };
        ensure!(
            min.is_none() && max.is_none(),
            MinMaxNeedRandomSnafu { kind: kind.name() }
        );
        Ok(kind)
    }

    fn name(&self) -> &'static str {
        match self {
            Kind::XSmall => "xsmall",
            Kind::Small => "small",
            Kind::Large => "large",
            Kind::XLarge => "xlarge",
            Kind::Mix => "mix",
            Kind::XMix => "xmix",
            Kind::Random { .. } => "random",
        }
    }

    /// files per side when `--count` isn't given
    fn default_count(&self) -> usize {
        match self {
            Kind::XSmall => 500,
            Kind::Small => 250,
            Kind::Large | Kind::XLarge => 25,
            Kind::Mix | Kind::XMix => 100,
            Kind::Random { .. } => 50,
        }
    }

    /// picks a file size from two random numbers
    fn size(&self, pick: u64, roll: u64) -> u64 {
        let (min, max) = match *self {
            Kind::XSmall => XSMALL,
            Kind::Small => SMALL,
            Kind::Large => LARGE,
            Kind::XLarge => XLARGE,
            Kind::Mix => [SMALL, LARGE][(pick % 2) as usize],
            Kind::XMix => [XSMALL, SMALL, LARGE, XLARGE][(pick % 4) as usize],
            Kind::Random { min, max } => (min, max),
        };
        // the range can only be all of u64 for random, and then any roll fits
        match (max - min).checked_add(1) {
            Some(span) => min + roll % span,
            None => roll,
        }
    }
}

/// one example folder. the name only depends on the settings, so the same settings always
/// map to the same folder, and the file contents are seeded from the name and path
struct Example {
    kind: Kind,
    /// files on each side, shared files count for both sides
    count: usize,
    entropy: Entropy,
}

impl Example {
    /// high entropy has no suffix, it was the only kind before `--entropy` existed
    fn name(&self) -> String {
        match self.entropy {
            Entropy::Low => format!("{}_low", self.seed()),
            Entropy::Med => format!("{}_med", self.seed()),
            Entropy::High => self.seed(),
        }
    }

    /// the name without the entropy, so the file sizes match across entropies
    fn seed(&self) -> String {
        match self.kind {
            Kind::Random { min, max } => format!("random_{}_{min}_{max}", self.count),
            kind => format!("{}_{}", kind.name(), self.count),
        }
    }

    /// (table, folder, files). about half the files are shared, the rest are split per side
    fn sections(&self) -> [(&'static str, &'static str, usize); 3] {
        let shared = self.count.div_ceil(2);
        let side = self.count - shared;
        [
            ("assets", "shared", shared),
            ("client.assets", "client", side),
            ("server.assets", "server", side),
        ]
    }
}

impl RegenArgs {
    /// the examples these flags ask for
    fn examples(&self) -> Result<Vec<Example>, ArgsError> {
        let Some(kind) = self.kind else {
            // clap's `requires` already rejects --count, --min and --max without --type
            return Ok(presets(self.entropy));
        };

        let kind = Kind::from_arg(kind, self.min, self.max)?;
        let count = match self.count {
            None => kind.default_count(),
            Some(count) => {
                usize::try_from(count).map_err(|_| CountTooBigSnafu { count }.build())?
            }
        };
        Ok(vec![Example {
            kind,
            count,
            entropy: self.entropy,
        }])
    }
}

/// what runs without `--type`, one of each type at its default count
fn presets(entropy: Entropy) -> Vec<Example> {
    [
        Kind::XSmall,
        Kind::Small,
        Kind::Large,
        Kind::XLarge,
        Kind::Mix,
        Kind::XMix,
        Kind::Random {
            min: DEFAULT_RANDOM_MIN,
            max: DEFAULT_RANDOM_MAX,
        },
    ]
    .into_iter()
    .map(|kind| Example {
        kind,
        count: kind.default_count(),
        entropy,
    })
    .collect()
}

/// makes each example that doesn't exist yet, and packs it with `--auto`. one failing
/// example doesn't stop the rest
pub fn run(args: RegenArgs) -> Result<(), RegenError> {
    let examples = args.examples().context(InvalidArgsSnafu)?;

    // the workspace root, so this works no matter where cargo is run from
    // xtask/ is always one level under it
    let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    let root = manifest_dir.parent().unwrap_or(manifest_dir);

    let mut failed: usize = 0;
    for example in &examples {
        let name = example.name();
        let dir = root.join(EXAMPLES_DIR).join(&name);

        if dir.join("manifest.toml").exists() {
            info!("{name} already exists at {}, not generating", dir.display());
        } else {
            let start = std::time::Instant::now();
            info!("Generating {name} at {}", dir.display());
            if let Err(e) = generate(example, &dir) {
                error!(
                    "Failed to generate example {name} after {:?}, skipping it: {}",
                    start.elapsed(),
                    Report::from_error(&e)
                );
                failed += 1;
                continue;
            }
            info!("Generated {name} in {:?}", start.elapsed());
        }

        if args.auto
            && let Err(e) = pkgen(root, &name, &dir)
        {
            error!("Failed to pack example {name}: {}", Report::from_error(&e));
            failed += 1;
        }
    }

    ensure!(
        failed == 0,
        SomeFailedSnafu {
            failed,
            total: examples.len()
        }
    );
    Ok(())
}

/// writes into a temp folder and renames it at the end, so a half written example is
/// never mistaken for a finished one
fn generate(example: &Example, dir: &Path) -> Result<(), GenerateError> {
    let tmp = dir.with_extension("tmp");
    if tmp.exists() {
        fs::remove_dir_all(&tmp).context(RemoveTmpSnafu { path: &tmp })?;
    }

    let name = example.name();
    let seed = example.seed();
    let mut manifest =
        String::from("realm_id = 1\nowner_id = 1\npack_version = 1\naccess = \"free\"\n");
    let mut total = 0;

    for (table, side, files) in example.sections() {
        manifest.push_str(&format!("\n[{table}]\n"));
        for i in 0..files {
            let group = format!("group{:02}", i / FILES_PER_GROUP);
            let item = format!("item{i:04}");
            let path = format!("{side}/{group}/{item}.bin");

            let folder = tmp.join(side).join(&group);
            fs::create_dir_all(&folder).context(CreateFolderSnafu { path: &folder })?;
            let full_path = tmp.join(&path);
            total += write_file(example, &seed, &path, &full_path).context(WriteFileSnafu {
                pack_path: &path,
                full_path: &full_path,
            })?;

            manifest.push_str(&format!("\"self:{side}/{group}/{item}\" = \"{path}\"\n"));
        }
    }

    let manifest_path = tmp.join("manifest.toml");
    fs::write(&manifest_path, manifest).context(WriteManifestSnafu {
        path: &manifest_path,
    })?;
    fs::rename(&tmp, dir).context(RenameSnafu {
        from: &tmp,
        to: dir,
    })?;
    info!("{name} has {} bytes of files", total);
    Ok(())
}

/// everything comes from a blake3 stream keyed by the seed and file path, so it's the
/// same every run. returns the file size
fn write_file(example: &Example, seed: &str, path: &str, out: &Path) -> std::io::Result<u64> {
    // the key predates the move into xtask, changing it would change every generated file
    let mut stream = blake3::Hasher::new_derive_key("terobit example_generator")
        .update(seed.as_bytes())
        .update(&[0])
        .update(path.as_bytes())
        .finalize_xof();

    let mut header = [0; 16];
    stream.fill(&mut header);
    let [pick, roll] = [&header[..8], &header[8..]]
        .map(|bytes| u64::from_le_bytes(bytes.try_into().unwrap_or_default()));
    let size = example.kind.size(pick, roll);
    let mut content = Content::new(example.entropy, stream);

    let mut file = fs::File::create(out)?;
    let mut buf = vec![0; MIB as usize];
    let mut left = size;
    while left > 0 {
        let n = left.min(buf.len() as u64) as usize;
        content.fill(&mut buf[..n]);
        file.write_all(&buf[..n])?;
        left -= n as u64;
    }
    Ok(size)
}

/// makes a file's bytes at some entropy, carrying patterns across `fill` calls
struct Content {
    entropy: Entropy,
    stream: blake3::OutputReader,
    /// random bytes read ahead, small reads straight from the stream are slow
    rolls: [u8; 4096],
    roll_at: usize,
    /// med: the words the file is built from
    words: Vec<Vec<u8>>,
    /// made but not written yet
    piece: Vec<u8>,
    piece_at: usize,
}

impl Content {
    fn new(entropy: Entropy, stream: blake3::OutputReader) -> Self {
        let mut content = Self {
            entropy,
            stream,
            rolls: [0; 4096],
            roll_at: 4096,
            words: Vec::new(),
            piece: Vec::new(),
            piece_at: 0,
        };
        if entropy == Entropy::Med {
            content.words = (0..MED_WORDS)
                .map(|_| {
                    let len = 4 + content.roll() as usize % 29;
                    (0..len).map(|_| content.roll()).collect()
                })
                .collect();
        }
        content
    }

    fn roll(&mut self) -> u8 {
        if self.roll_at == self.rolls.len() {
            self.stream.fill(&mut self.rolls);
            self.roll_at = 0;
        }
        self.roll_at += 1;
        self.rolls[self.roll_at - 1]
    }

    fn fill(&mut self, buf: &mut [u8]) {
        if self.entropy == Entropy::High {
            self.stream.fill(buf);
            return;
        }

        let mut done = 0;
        while done < buf.len() {
            if self.piece_at == self.piece.len() {
                self.next_piece();
            }
            let n = (buf.len() - done).min(self.piece.len() - self.piece_at);
            buf[done..done + n].copy_from_slice(&self.piece[self.piece_at..self.piece_at + n]);
            done += n;
            self.piece_at += n;
        }
    }

    fn next_piece(&mut self) {
        self.piece.clear();
        self.piece_at = 0;
        match self.entropy {
            Entropy::Low => {
                let byte = LOW_BYTES[self.roll() as usize % LOW_BYTES.len()];
                let len = 16 + self.roll() as usize;
                self.piece.resize(len, byte);
            }
            Entropy::Med => {
                // one in eight pieces is a few bytes of noise, the rest are words
                if self.roll().is_multiple_of(8) {
                    let len = 1 + self.roll() as usize % 8;
                    for _ in 0..len {
                        let byte = self.roll();
                        self.piece.push(byte);
                    }
                } else {
                    let word = self.roll() as usize % MED_WORDS;
                    self.piece.extend_from_slice(&self.words[word]);
                }
            }
            Entropy::High => unreachable!("high entropy fills straight from the stream"),
        }
    }
}

/// packs the example, same as `cargo xtask pkgen --manifest <dir>/manifest.toml --out <out>`
fn pkgen(root: &Path, name: &str, dir: &Path) -> Result<(), pkgen::PkgenError> {
    let args = pkgen::PkgenArgs {
        manifest: dir.join("manifest.toml"),
        out: root.join(PACKS_DIR).join(name),
        target: pkgen::TargetArg::Both,
        zstd_level: pkgen::ZstdLevel(Some(ZSTD_LEVEL)),
    };
    info!("Packing {name}, packs go to {}", args.out.display());
    pkgen::run(&args)
}

#[cfg(test)]
mod fn_tests {
    use clap::Parser;

    use super::*;

    #[derive(Parser)]
    struct TestCli {
        #[command(flatten)]
        args: RegenArgs,
    }

    /// parses like `cargo xtask regen <args>`, a clap error and an `ArgsError` both count
    fn examples(args: &[&str]) -> Option<(Vec<Example>, bool)> {
        let cli =
            TestCli::try_parse_from(std::iter::once("regen").chain(args.iter().copied())).ok()?;
        let examples = cli.args.examples().ok()?;
        Some((examples, cli.args.auto))
    }

    #[test]
    fn no_flags_is_every_preset() {
        let (examples, auto) = examples(&[]).unwrap();
        assert_eq!(examples.len(), 7);
        assert!(!auto);
    }

    #[test]
    fn names_are_deterministic() {
        let (ex, _) = examples(&[
            "--type", "random", "--count", "3", "--min", "5", "--max", "9",
        ])
        .unwrap();
        assert_eq!(ex[0].name(), "random_3_5_9");
        let (ex, auto) = examples(&["--type", "xlarge", "--auto"]).unwrap();
        assert_eq!(ex[0].name(), "xlarge_25");
        assert!(auto);
        let (ex, _) = examples(&["--type", "small", "--entropy", "med"]).unwrap();
        assert_eq!(ex[0].name(), "small_250_med");
        assert_eq!(ex[0].seed(), "small_250");
    }

    #[test]
    fn entropy_applies_to_presets() {
        let (ex, _) = examples(&["--entropy", "low"]).unwrap();
        assert!(ex.iter().all(|e| e.entropy == Entropy::Low));
    }

    #[test]
    fn content_is_deterministic_across_fills() {
        for entropy in [Entropy::Low, Entropy::Med, Entropy::High] {
            let stream = || blake3::Hasher::new().update(b"seed").finalize_xof();
            let mut whole = vec![0; 10_000];
            Content::new(entropy, stream()).fill(&mut whole);

            let mut split = vec![0; 10_000];
            let mut content = Content::new(entropy, stream());
            for chunk in split.chunks_mut(333) {
                content.fill(chunk);
            }
            assert_eq!(whole, split, "{entropy:?}");
        }
    }

    #[test]
    fn rejects_bad_flags() {
        assert!(examples(&["--type", "huge"]).is_none());
        assert!(examples(&["--type", "small", "--min", "1"]).is_none());
        assert!(examples(&["--type", "random", "--min", "9", "--max", "5"]).is_none());
        assert!(examples(&["--type", "small", "--count", "0"]).is_none());
        assert!(examples(&["--count", "5"]).is_none());
        assert!(examples(&["--auto", "yes"]).is_none());
        assert!(examples(&["--size", "5"]).is_none());
        assert!(examples(&["--entropy", "max"]).is_none());
    }

    #[test]
    fn sides_get_count_files() {
        for count in [1, 2, 25] {
            let [shared, client, server] = Example {
                kind: Kind::Small,
                count,
                entropy: Entropy::High,
            }
            .sections();
            assert_eq!(shared.2 + client.2, count);
            assert_eq!(shared.2 + server.2, count);
        }
    }

    #[test]
    fn sizes_stay_in_range() {
        let kind = Kind::Random { min: 10, max: 12 };
        for roll in 0..100 {
            assert!((10..=12).contains(&kind.size(roll, roll)));
        }
        assert_eq!(
            Kind::Random {
                min: 0,
                max: u64::MAX
            }
            .size(0, 7),
            7
        );
    }
}
